css:
.logi611-container {
    padding: 24px;
    background: #eceff4;
    min-height: 100vh;
    font-family: 'Inter', -apple-system, 'Segoe UI', sans-serif;
    color: #1e293b;
}
.logi611-container h1, .logi611-container h3 { margin: 0; }
.logi611-header {
    background: linear-gradient(135deg, #1e293b 0%, #334155 100%);
    border-left: 6px solid #f59e0b;
    padding: 24px 32px;
    color: #f1f5f9;
    margin-bottom: 20px;
    border-radius: 4px;
}
.logi611-header-label {
    font-size: 0.72rem;
    color: #94a3b8;
    letter-spacing: 0.15em;
    text-transform: uppercase;
    margin-bottom: 6px;
}
.logi611-header h1 {
    font-size: 1.55rem;
    font-weight: 700;
    color: #ffffff;
    letter-spacing: 0.02em;
}
.logi611-header-sub {
    font-size: 0.9rem;
    color: #cbd5e1;
    margin-top: 6px;
}
.logi611-period-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #cbd5e1;
    border-top: 3px solid #0ea5e9;
    padding: 14px 20px;
    margin-bottom: 18px;
    border-radius: 4px;
}
.logi611-period-text {
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: #64748b;
    font-weight: 600;
}
.logi611-period-text span:nth-child(2) {
    color: #0ea5e9;
    font-size: 1.1rem;
    margin: 0 6px;
}
.logi611-period-title {
    font-size: 0.95rem;
    font-weight: 700;
    color: #1e293b;
    text-transform: uppercase;
    letter-spacing: 0.08em;
}
.logi611-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 14px;
    margin-bottom: 20px;
}
.logi611-kpi-card {
    background: #ffffff;
    border: 1px solid #cbd5e1;
    padding: 18px 20px;
    border-radius: 4px;
    position: relative;
    overflow: hidden;
}
.logi611-kpi-card::before {
    content: '';
    position: absolute;
    left: 0; top: 0; bottom: 0;
    width: 4px;
    background: #64748b;
}
.logi611-kpi-highlight::before { background: #059669; }
.logi611-kpi-label {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #64748b;
    margin-bottom: 8px;
    font-weight: 600;
}
.logi611-kpi-value {
    font-size: 1.7rem;
    font-weight: 700;
    color: #1e293b;
    font-variant-numeric: tabular-nums;
}
.logi611-kpi-highlight .logi611-kpi-value { color: #059669; }
.logi611-briefing {
    background: #ffffff;
    border: 1px solid #cbd5e1;
    border-left: 4px solid #f59e0b;
    padding: 20px 24px;
    margin-bottom: 18px;
    border-radius: 4px;
}
.logi611-briefing h3 {
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: #f59e0b;
    margin-bottom: 12px;
}
.logi611-briefing-text {
    font-size: 0.95rem;
    line-height: 1.6;
    color: #334155;
}
.logi611-controls {
    background: #ffffff;
    border: 1px solid #cbd5e1;
    padding: 22px 24px;
    margin-bottom: 20px;
    border-radius: 4px;
}
.logi611-controls h3 {
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: #64748b;
    margin-bottom: 16px;
    padding-bottom: 10px;
    border-bottom: 1px solid #e2e8f0;
}
.logi611-decision-group {
    margin-bottom: 14px;
}
.logi611-decision-group label {
    display: block;
    font-size: 0.78rem;
    font-weight: 600;
    color: #475569;
    margin-bottom: 6px;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}
.logi611-controls select,
.logi611-controls input {
    width: 100%;
    background: #f8fafc;
    border: 1px solid #cbd5e1;
    color: #1e293b;
    padding: 10px 12px;
    border-radius: 3px;
    font-size: 0.92rem;
    font-family: inherit;
    transition: border-color 0.2s ease;
}
.logi611-controls select:focus,
.logi611-controls input:focus {
    outline: none;
    border-color: #0ea5e9;
    background: #ffffff;
}
.logi611-controls .btn-primary {
    background: #0ea5e9;
    border-color: #0ea5e9;
    color: #ffffff;
    font-weight: 600;
    padding: 11px 28px;
    margin-top: 14px;
    margin-right: 8px;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-size: 0.82rem;
    border-radius: 3px;
}
.logi611-controls .btn-primary:hover {
    background: #0284c7;
    border-color: #0284c7;
}
.logi611-controls .btn-outline-secondary {
    padding: 11px 20px;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    border-radius: 3px;
}
.logi611-section {
    background: #ffffff;
    border: 1px solid #cbd5e1;
    padding: 20px 24px;
    margin-bottom: 18px;
    border-radius: 4px;
}
.logi611-section h3 {
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: #64748b;
    margin-bottom: 14px;
    padding-bottom: 10px;
    border-bottom: 1px solid #e2e8f0;
}
.logi611-chart-wrapper {
    position: relative;
    height: 320px;
}
#usfHistoryTable {
    font-size: 0.88rem;
    margin: 0;
}
#usfHistoryTable thead th {
    background: #f1f5f9;
    color: #475569;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    border-bottom: 2px solid #cbd5e1;
}
#usfHistoryTable tbody td {
    font-variant-numeric: tabular-nums;
    color: #334155;
}
@media (max-width: 768px) {
    .logi611-container { padding: 14px; }
    .logi611-header { padding: 18px 20px; }
    .logi611-header h1 { font-size: 1.2rem; }
    .logi611-period-bar { flex-direction: column; align-items: flex-start; gap: 6px; }
    .logi611-kpi-value { font-size: 1.3rem; }
}

