        getHint(state, results) {
            if (!results) return null;
            if (results.period === 1 && state.domainState.route === 'B' && state.domainState.customerApproval === 'none') {
                return window.mySimulation.t('hint_no_approval');
            }
            if (results.period === 2 && state.domainState.insurance === 'named') {
                return window.mySimulation.t('hint_named_peril');
            }
            if (results.period === 2 && state.domainState.route === 'B' && state.domainState.transshipment === 'deposito') {
                return window.mySimulation.t('hint_deposito');
            }
            if (results.period === 4 && state.domainState.damageEvent && !state.domainState.insuranceCovered) {
                return window.mySimulation.t('hint_uninsured_loss');
            }
            return null;
